using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

namespace RTXMnesia.Player
{
    /// <summary>cLuxPlayerFlashback's .flash voices, generated by FlashbackConverter in Resources/HplFlashbacks.asset.</summary>
    public sealed class HplFlashbackAssets : ScriptableObject
    {
        public const string ResourceName = "HplFlashbacks";

        [Serializable]
        public sealed class VoiceData
        {
            public string voiceSound, effectSound, textCat, textEntry;
        }

        [Serializable]
        public sealed class FlashbackData
        {
            public string name;
            public List<VoiceData> voices = new();
        }

        public List<FlashbackData> flashbacks = new();

        public FlashbackData Find(string file)
        {
            string name = Path.GetFileNameWithoutExtension((file ?? "").Replace('\\', '/'));
            foreach (var flashback in flashbacks)
                if (string.Equals(flashback.name, name, StringComparison.OrdinalIgnoreCase)) return flashback;
            return null;
        }
    }
}
